&lt;ActionGrid&gt;
  &lt;Settings&gt;
    &lt;Version&gt;5.28.0&lt;/Version&gt;
    &lt;Build&gt;5.28.314&lt;/Build&gt;
    &lt;CurrentContext&gt;ExportImport&lt;/CurrentContext&gt;
    &lt;ModuleId&gt;1230&lt;/ModuleId&gt;
    &lt;DataSource&gt;{&quot;DefinitionId&quot;:&quot;SqlQuery&quot;,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:&quot;&quot;,&quot;QueryTimeout&quot;:&quot;&quot;,&quot;SqlQuery&quot;:&quot;DECLARE @StatusDraft INT;

SELECT TOP (1)
    @StatusDraft = Id
FROM app.StatusCalcul
WHERE UPPER(LTRIM(RTRIM(Denumire))) = &#39;DRAFT&#39;
ORDER BY Id;

UPDATE c
SET c.Valid = 0
FROM app.CardRZB c
WHERE c.CodSucursala = @CodSucursala
  AND ISNULL(c.Valid, 1) = 1
  AND @StatusDraft IS NOT NULL

  -- Salariatul nu mai exista in sesiunea curenta
  AND NOT EXISTS
  (
      SELECT 1
      FROM app.Salariat s
      WHERE LTRIM(RTRIM(s.Marca)) = LTRIM(RTRIM(c.Marca))
        AND s.CodSucursala = c.CodSucursala
        AND s.Anul = @Anul
        AND s.Luna = @Luna
  )

  -- Nu invalidam automat cardul daca exista sume iesite din Draft
  AND NOT EXISTS
  (
      SELECT 1
      FROM
      (
          SELECT Marca, CodSucursala, Anul, Luna, Status
          FROM app.SumaBCR

          UNION ALL

          SELECT Marca, CodSucursala, Anul, Luna, Status
          FROM app.SumaBRD

          UNION ALL

          SELECT Marca, CodSucursala, Anul, Luna, Status
          FROM app.SumaBT

          UNION ALL

          SELECT Marca, CodSucursala, Anul, Luna, Status
          FROM app.SumaCEC

          UNION ALL

          SELECT Marca, CodSucursala, Anul, Luna, Status
          FROM app.SumaING

          UNION ALL

          SELECT Marca, CodSucursala, Anul, Luna, Status
          FROM app.SumaEXM

          UNION ALL

          SELECT Marca, CodSucursala, Anul, Luna, Status
          FROM app.SumaRZB

          UNION ALL

          SELECT Marca, CodSucursala, Anul, Luna, Status
          FROM app.SumaUNI

          UNION ALL

          SELECT Marca, CodSucursala, Anul, Luna, Status
          FROM app.SumaALTE
      ) sx
      WHERE LTRIM(RTRIM(sx.Marca)) = LTRIM(RTRIM(c.Marca))
        AND sx.CodSucursala = c.CodSucursala
        AND sx.Anul = @Anul
        AND sx.Luna = @Luna
        AND ISNULL(sx.Status, -1) &amp;lt;&amp;gt; @StatusDraft
  );

SELECT
    c.Id,
    c.CodSucursala,
    c.Marca,
    c.Nume,
    c.CNP,
    c.ContIBAN,
    c.IdClientRAIFF,
    c.DAC,
    c.Valid
FROM app.CardRZB c
WHERE c.CodSucursala = @CodSucursala
ORDER BY c.Marca;&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOrSession:BranchV]&quot;,&quot;name&quot;:&quot;CodSucursala&quot;},{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;Anul&quot;},{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;Luna&quot;}],&quot;IdColumn&quot;:&quot;Id&quot;,&quot;SqlQueryColumns&quot;:&quot;Id
CodSucursala
Marca
Nume
CNP
ContIBAN
IdClientRAIFF
DAC
Valid&quot;,&quot;SqlQueryInsert&quot;:&quot;&quot;,&quot;SqlQueryUpdate&quot;:&quot;&quot;,&quot;SqlQueryDelete&quot;:&quot;&quot;,&quot;AddUrl&quot;:&quot;&quot;,&quot;EditUrl&quot;:&quot;&quot;,&quot;ViewUrl&quot;:&quot;&quot;},&quot;Fields&quot;:[{&quot;Title&quot;:null,&quot;Name&quot;:&quot;Id&quot;,&quot;TypeStr&quot;:&quot;System.Void, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:false,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:null,&quot;Name&quot;:&quot;CodSucursala&quot;,&quot;TypeStr&quot;:&quot;System.Void, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:false,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:null,&quot;Name&quot;:&quot;Marca&quot;,&quot;TypeStr&quot;:&quot;System.Void, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:false,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:null,&quot;Name&quot;:&quot;Nume&quot;,&quot;TypeStr&quot;:&quot;System.Void, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:false,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:null,&quot;Name&quot;:&quot;CNP&quot;,&quot;TypeStr&quot;:&quot;System.Void, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:false,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:null,&quot;Name&quot;:&quot;ContIBAN&quot;,&quot;TypeStr&quot;:&quot;System.Void, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:false,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:null,&quot;Name&quot;:&quot;IdClientRAIFF&quot;,&quot;TypeStr&quot;:&quot;System.Void, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:false,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:null,&quot;Name&quot;:&quot;DAC&quot;,&quot;TypeStr&quot;:&quot;System.Void, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:false,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:null,&quot;Name&quot;:&quot;Valid&quot;,&quot;TypeStr&quot;:&quot;System.Void, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:false,&quot;DefaultValue&quot;:null}]}&lt;/DataSource&gt;
    &lt;ShowTitle&gt;True&lt;/ShowTitle&gt;
    &lt;NoDataMessage&gt;No Data&lt;/NoDataMessage&gt;
    &lt;AditionalHtmlHeader /&gt;
    &lt;OnInitJs /&gt;
    &lt;OnRefreshJs /&gt;
    &lt;EnableEmbed&gt;False&lt;/EnableEmbed&gt;
    &lt;ShowCondition /&gt;
    &lt;SearchPlaceholder&gt;Search&lt;/SearchPlaceholder&gt;
    &lt;SearchDelayTime&gt;300&lt;/SearchDelayTime&gt;
    &lt;TableHeight /&gt;
    &lt;PagerStyle&gt;TouchFriendly&lt;/PagerStyle&gt;
    &lt;DisplayMode&gt;Always&lt;/DisplayMode&gt;
    &lt;PopupWidth /&gt;
    &lt;WidthCoordinate&gt;px&lt;/WidthCoordinate&gt;
    &lt;PopupName /&gt;
    &lt;PageSizes&gt;[12,24,48]&lt;/PageSizes&gt;
    &lt;DefaultPageSize&gt;12&lt;/DefaultPageSize&gt;
    &lt;IsDebug&gt;False&lt;/IsDebug&gt;
    &lt;SearchEnabled&gt;True&lt;/SearchEnabled&gt;
    &lt;ExactSearch&gt;False&lt;/ExactSearch&gt;
    &lt;HideEmptyGrid&gt;False&lt;/HideEmptyGrid&gt;
    &lt;LoadOnSearch&gt;False&lt;/LoadOnSearch&gt;
    &lt;HideTableHead&gt;False&lt;/HideTableHead&gt;
    &lt;EnableStickyHead&gt;False&lt;/EnableStickyHead&gt;
    &lt;ItemButtonPosition&gt;Right&lt;/ItemButtonPosition&gt;
    &lt;ItemButtonPositionInColumn&gt;Right&lt;/ItemButtonPositionInColumn&gt;
    &lt;ItemButtonGroupingOptions&gt;HorizontalAlign&lt;/ItemButtonGroupingOptions&gt;
    &lt;FiltersEnabled&gt;True&lt;/FiltersEnabled&gt;
    &lt;ShowFilters&gt;False&lt;/ShowFilters&gt;
    &lt;SyncUrl&gt;True&lt;/SyncUrl&gt;
    &lt;IncludeBootstrapJS&gt;True&lt;/IncludeBootstrapJS&gt;
    &lt;IncludeBootstrapCSS&gt;True&lt;/IncludeBootstrapCSS&gt;
    &lt;IncludeFontAwesome&gt;True&lt;/IncludeFontAwesome&gt;
    &lt;AngularnoConflict&gt;True&lt;/AngularnoConflict&gt;
    &lt;SelectAllPosition&gt;None&lt;/SelectAllPosition&gt;
    &lt;SearchPosition&gt;expandabletop&lt;/SearchPosition&gt;
    &lt;RootCSSClasses /&gt;
    &lt;ModalRefresh&gt;False&lt;/ModalRefresh&gt;
    &lt;ShowLoading&gt;True&lt;/ShowLoading&gt;
    &lt;TabsProLoading&gt;True&lt;/TabsProLoading&gt;
    &lt;EnableGridSelect&gt;True&lt;/EnableGridSelect&gt;
    &lt;DataSourceAutoRefreshInterval&gt;1&lt;/DataSourceAutoRefreshInterval&gt;
    &lt;DataSourceRefreshType&gt;manual&lt;/DataSourceRefreshType&gt;
    &lt;DateFormat&gt;m/d/yy&lt;/DateFormat&gt;
    &lt;ItemButtonGroups&gt;[]&lt;/ItemButtonGroups&gt;
    &lt;GridButtonGroups&gt;[]&lt;/GridButtonGroups&gt;
    &lt;ItemButtons&gt;[{&quot;ItemActions&quot;:[{&quot;Id&quot;:-1,&quot;IsDeleted&quot;:false,&quot;ActionInfo&quot;:{&quot;Id&quot;:-1,&quot;GlobalId&quot;:&quot;016acb83-8074-4fde-a927-58359d67d641&quot;,&quot;Description&quot;:null,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:-1,&quot;ActionType&quot;:&quot;OpenAFPopup&quot;,&quot;Condition&quot;:null,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:0,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;ModuleId&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;17ff6222-786e-43b2-bc79-efa6c3e2c16f&quot;},&quot;ReinitForm&quot;:true,&quot;Params&quot;:[{&quot;name&quot;:&quot;CardRZBId&quot;,&quot;value&quot;:&quot;[Id]&quot;}],&quot;AllowUserClose&quot;:true,&quot;CloseOnClick&quot;:true,&quot;CloseOnEscape&quot;:true},&quot;Metadata&quot;:{&quot;PAP_InternalIdentifier&quot;:&quot;Button.Edit.OpenForm&quot;},&quot;HasActionParameters&quot;:true}}],&quot;OnItemClickActionStackId&quot;:-1,&quot;Url&quot;:&quot;&amp;amp;buttonName=Edit&quot;,&quot;ModuleId&quot;:1230,&quot;AutoName&quot;:false,&quot;Name&quot;:&quot;Edit&quot;,&quot;Title&quot;:&quot;&quot;,&quot;Help&quot;:&quot;Modifica&quot;,&quot;ShowCondition&quot;:&quot;([HasRole:Admins] || [HasRole:CitizenDevelopers] || [HasRole:Low-CodeEngineer] || [HasRole:Managers])&quot;,&quot;IsEnabled&quot;:false,&quot;Metadata&quot;:{&quot;PAP_InternalIdentifier&quot;:&quot;Button.Edit&quot;},&quot;Type&quot;:&quot;ItemButton&quot;,&quot;OrderIndex&quot;:0,&quot;CssClass&quot;:&quot;default&quot;,&quot;CustomCssClass&quot;:null,&quot;IconClass&quot;:&quot;&quot;,&quot;FaIconClass&quot;:&quot;fas fa-pen&quot;,&quot;PermissionAllUsers&quot;:false,&quot;PermissionsExportJson&quot;:&quot;[\&quot;Admins\&quot;,\&quot;Citizen Developers\&quot;,\&quot;Low-Code Engineer\&quot;,\&quot;Managers\&quot;]&quot;,&quot;Permissions&quot;:[6,7,5,8],&quot;AskForConfirmation&quot;:false,&quot;ConfirmationMessage&quot;:null,&quot;ConfirmationOk&quot;:null,&quot;ConfirmationCancel&quot;:null,&quot;JsCode&quot;:null,&quot;IsClientButton&quot;:false,&quot;ButtonGroupId&quot;:null,&quot;ButtonGroupName&quot;:null,&quot;Id&quot;:0,&quot;EnableCondition&quot;:null,&quot;IsDeleted&quot;:false},{&quot;ItemActions&quot;:[{&quot;Id&quot;:-1,&quot;IsDeleted&quot;:false,&quot;ActionInfo&quot;:{&quot;Id&quot;:-1,&quot;GlobalId&quot;:&quot;cfae9a42-55f9-4837-bb82-1a673a1c1a96&quot;,&quot;Description&quot;:&quot;Invalideaza card&quot;,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:-1,&quot;ActionType&quot;:&quot;RunSql&quot;,&quot;Condition&quot;:null,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:0,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:null,&quot;QueryTimeout&quot;:null,&quot;UseTransactions&quot;:true,&quot;SqlQuery&quot;:&quot;DECLARE @StatusDraft INT;
DECLARE @Marca NVARCHAR(100);
DECLARE @CodSucursalaCard NVARCHAR(50);

SELECT TOP (1)
    @StatusDraft = Id
FROM app.StatusCalcul
WHERE UPPER(LTRIM(RTRIM(Denumire))) = &#39;DRAFT&#39;
ORDER BY Id;

IF @StatusDraft IS NULL
BEGIN
    RAISERROR(
        N&#39;Nu a fost identificat statusul Draft in app.StatusCalcul.&#39;,
        16,
        1
    );
    RETURN;
END;

SELECT
    @Marca = LTRIM(RTRIM(c.Marca)),
    @CodSucursalaCard = c.CodSucursala
FROM app.CardRZB c
WHERE c.Id = @Id
  AND c.CodSucursala = @CodSucursala;

IF @Marca IS NULL
BEGIN
    RAISERROR(
        N&#39;Cardul RZB selectat nu a fost gasit in sucursala curenta.&#39;,
        16,
        1
    );
    RETURN;
END;

IF EXISTS
(
    SELECT 1
    FROM
    (
        SELECT Marca, CodSucursala, Anul, Luna, Status
        FROM app.SumaBCR

        UNION ALL

        SELECT Marca, CodSucursala, Anul, Luna, Status
        FROM app.SumaBRD

        UNION ALL

        SELECT Marca, CodSucursala, Anul, Luna, Status
        FROM app.SumaBT

        UNION ALL

        SELECT Marca, CodSucursala, Anul, Luna, Status
        FROM app.SumaCEC

        UNION ALL

        SELECT Marca, CodSucursala, Anul, Luna, Status
        FROM app.SumaING

        UNION ALL

        SELECT Marca, CodSucursala, Anul, Luna, Status
        FROM app.SumaEXM

        UNION ALL

        SELECT Marca, CodSucursala, Anul, Luna, Status
        FROM app.SumaRZB

        UNION ALL

        SELECT Marca, CodSucursala, Anul, Luna, Status
        FROM app.SumaUNI

        UNION ALL

        SELECT Marca, CodSucursala, Anul, Luna, Status
        FROM app.SumaALTE
    ) sx
    WHERE LTRIM(RTRIM(sx.Marca)) = @Marca
      AND sx.CodSucursala = @CodSucursalaCard
      AND sx.Anul = @Anul
      AND sx.Luna = @Luna
      AND ISNULL(sx.Status, -1) &amp;lt;&amp;gt; @StatusDraft
)
BEGIN
    RAISERROR(
        N&#39;Cardul nu poate fi dezactivat deoarece exista sume confirmate sau aflate in fluxul de plata.&#39;,
        16,
        1
    );
    RETURN;
END;

UPDATE app.CardRZB
SET Valid = 0
WHERE Id = @Id
  AND CodSucursala = @CodSucursala;&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[Id]&quot;,&quot;name&quot;:&quot;Id&quot;},{&quot;value&quot;:&quot;[GetOrSession:BranchV]&quot;,&quot;name&quot;:&quot;CodSucursala&quot;},{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;Anul&quot;},{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;Luna&quot;}],&quot;OutputTokenName&quot;:null,&quot;ExtractColumns&quot;:null,&quot;OnError&quot;:[{&quot;Id&quot;:9083,&quot;GlobalId&quot;:&quot;00000000-0000-0000-0000-000000000000&quot;,&quot;Description&quot;:null,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:10495,&quot;ActionType&quot;:&quot;ShowError&quot;,&quot;Condition&quot;:null,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:0,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;Message&quot;:&quot;&amp;lt;p&amp;gt;Cardul nu poate fi dezactivat deoarece există sume confirmate sau aflate &#238;n fluxul de plată.&amp;lt;br&amp;gt;&amp;lt;/p&amp;gt;&quot;,&quot;AllowHtml&quot;:true},&quot;Metadata&quot;:{},&quot;HasActionParameters&quot;:true}],&quot;ShowErrors&quot;:false},&quot;Metadata&quot;:{},&quot;HasActionParameters&quot;:true}},{&quot;Id&quot;:-1,&quot;IsDeleted&quot;:false,&quot;ActionInfo&quot;:{&quot;Id&quot;:-1,&quot;GlobalId&quot;:&quot;1bca6689-fdcd-4ed6-8184-4ddbff5d261e&quot;,&quot;Description&quot;:null,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:-1,&quot;ActionType&quot;:&quot;DataSource.Refresh&quot;,&quot;Condition&quot;:null,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:1,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{},&quot;Metadata&quot;:{&quot;PAP_InternalIdentifier&quot;:&quot;Button.Delete.RefreshDatasource&quot;},&quot;HasActionParameters&quot;:true}}],&quot;OnItemClickActionStackId&quot;:-1,&quot;Url&quot;:&quot;&am